'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value-float64array' );
var dlasq6 = require( './../lib/dlasq6.js' );


// FIXTURES //

var PING = require( './fixtures/ping.json' );
var PONG = require( './fixtures/pong.json' );
var QUICK_RET = require( './fixtures/quick_ret.json' );
var ZER_DEF_PING = require( './fixtures/zero_deflation_ping.json' );
var ZER_DEF_PONG = require( './fixtures/zero_deflation_pong.json' );
var DIV_FALLBACK_PING = require( './fixtures/div_fallback_ping.json' );
var DIV_FALLBACK_PONG = require( './fixtures/div_fallback_pong.json' );
var ZERO_DEF_FIRST_UNROLL = require( './fixtures/zero_def_first_unroll.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dlasq6, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 5', function test( t ) {
	t.strictEqual( dlasq6.length, 5, 'returns expected value' );
	t.end();
});

tape( 'the function computes one dqd transform in ping-pong form', function test( t ) {
	var expectedZ;
	var expected;
	var data;
	var out;
	var Z;

	data = PING;

	Z = new Float64Array( data.Z );
	out = new Float64Array( 6 );

	expected = new Float64Array( data.expectedOut );
	expectedZ = new Float64Array( data.Z_out );

	dlasq6( data.I0, data.N0, Z, data.PP, out );
	t.strictEqual( isAlmostSameValue( out, expected, 1 ), true, 'returns expected value' );
	t.strictEqual( isAlmostSameValue( Z, expectedZ, 1 ), true, 'returns expected value' );

	data = PONG;

	Z = new Float64Array( data.Z );
	out = new Float64Array( 6 );

	expected = new Float64Array( data.expectedOut );
	expectedZ = new Float64Array( data.Z_out );

	dlasq6( data.I0, data.N0, Z, data.PP, out );
	t.strictEqual( isAlmostSameValue( out, expected, 1 ), true, 'returns expected value' );
	t.strictEqual( isAlmostSameValue( Z, expectedZ, 1 ), true, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided a first argument which is less than zero', function test( t ) {
	var values;
	var data;
	var out;
	var i;
	var Z;

	data = PING;

	Z = new Float64Array( data.Z );
	out = new Float64Array( data.output );

	values = [
		-1,
		-2,
		-3
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), RangeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dlasq6( value, data.N0, Z, data.PP, out );
		};
	}
});

